import{_ as a,c as A,o as t,a4 as r}from"./chunks/framework.UazWDHJY.js";const o="/article/assets/vector01.BHHbVEB9.jpg",i="data:image/jpeg;base64,",s="data:image/jpeg;base64,",e="data:image/jpeg;base64,",n="/article/assets/vector06.BiZDeJTL.jpg",c="/article/assets/vector07.CdusUFV4.jpg",p="/article/assets/vector08.C1nfkyO9.jpg",l="/article/assets/vector05.RK47i_9r.jpg",g="/article/assets/vector09.D9-8czZ2.jpg",m="/article/assets/vector10.1LqOjaqa.jpg",j="/article/assets/vector11.YDgCWI56.jpg",f="/article/assets/vector12.9HrNUN7k.jpg",h="/article/assets/vector13.oRvs5UqO.jpg",B="/article/assets/vector14.CBZ9-l7x.jpg",F="/article/assets/vector15.ClnEPLi3.jpg",x="/article/assets/matrix00.BlrTNJhZ.jpg",K="/article/assets/transform00.DwSoTkDq.jpg",D="/article/assets/transform01.CorFJpC2.jpg",R="/article/assets/transform02.D8WK-puC.jpg",P="/article/assets/transform03.BOGEHVD9.jpg",d="/article/assets/transform04.D7y1mwQc.jpg",U="/article/assets/transform05.BHKM25OP.jpg",Q="/article/assets/transform06.C6C_Zjjb.jpg",E="/article/assets/transform07.CmJDiNAA.jpg",w="/article/assets/transform08.BX-eBgj1.jpg",H="/article/assets/transform09.D5Lx2p6F.jpg",v="/article/assets/transform10.DbTDu9Yz.jpg",M="/article/assets/transform11.CzpTz-B5.jpg",u="/article/assets/transform12.an-5U3rA.jpg",X=JSON.parse('{"title":"计算机图形图数学基础整理","description":"","frontmatter":{},"headers":[],"relativePath":"cg/mathematics-for-cg.md","filePath":"cg/mathematics-for-cg.md"}'),I={name:"cg/mathematics-for-cg.md"},q=r('<h1 id="计算机图形图数学基础整理" tabindex="-1">计算机图形图数学基础整理 <a class="header-anchor" href="#计算机图形图数学基础整理" aria-label="Permalink to &quot;计算机图形图数学基础整理&quot;">​</a></h1><blockquote><p>内容出自GAMES101课程 <a href="https://sites.cs.ucsb.edu/~lingqi/teaching/games101.html" target="_blank" rel="noreferrer">https://sites.cs.ucsb.edu/~lingqi/teaching/games101.html</a></p></blockquote><blockquote><p><a href="https://sites.cs.ucsb.edu/~lingqi/teaching/games101.html" target="_blank" rel="noreferrer">https://sites.cs.ucsb.edu/~lingqi/teaching/games101.html</a></p></blockquote><h2 id="vectors-向量" tabindex="-1">Vectors 向量 <a class="header-anchor" href="#vectors-向量" aria-label="Permalink to &quot;Vectors 向量&quot;">​</a></h2><p><strong>表示一段具有长度的方向</strong></p><p><img src="'+o+'" alt=""></p><p>数学表示符号:</p><p><img src="'+i+'" alt=""></p><p><strong>矢量的两个意义</strong></p><ol><li>方向</li><li>长度</li></ol><h3 id="vector-normalization-向量标准化或向量归一化" tabindex="-1">Vector Normalization 向量标准化或向量归一化 <a class="header-anchor" href="#vector-normalization-向量标准化或向量归一化" aria-label="Permalink to &quot;Vector Normalization 向量标准化或向量归一化&quot;">​</a></h3><p>向量的长度表示符号:</p><p><img src="'+s+'" alt=""></p><p><strong>单位向量:</strong></p><ol><li>长度为1</li><li>用于表示一个方向</li></ol><p>任意向量的单位向量计算也可成为归一化:</p><p><img src="'+e+'" alt=""></p><h3 id="cartesian-coordinates-笛卡尔坐标系" tabindex="-1">Cartesian Coordinates 笛卡尔坐标系 <a class="header-anchor" href="#cartesian-coordinates-笛卡尔坐标系" aria-label="Permalink to &quot;Cartesian Coordinates 笛卡尔坐标系&quot;">​</a></h3><p><strong>X 和 Y 轴通常是正交的单位向量</strong></p><p>图形学中约定向量A的矩阵表示法</p><p><img src="'+n+'" alt=""></p><p>向量A的转置矩阵</p><p><img src="'+c+'" alt=""></p><p>向量A的长度</p><p><img src="'+p+'" alt=""></p><h3 id="vector-addition-向量加法" tabindex="-1">Vector Addition 向量加法 <a class="header-anchor" href="#vector-addition-向量加法" aria-label="Permalink to &quot;Vector Addition 向量加法&quot;">​</a></h3><p><img src="'+l+'" alt=""></p><h3 id="vector-multiplication-向量乘法" tabindex="-1">Vector Multiplication 向量乘法 <a class="header-anchor" href="#vector-multiplication-向量乘法" aria-label="Permalink to &quot;Vector Multiplication 向量乘法&quot;">​</a></h3><h4 id="dot-product-点乘" tabindex="-1">Dot product 点乘 <a class="header-anchor" href="#dot-product-点乘" aria-label="Permalink to &quot;Dot product 点乘&quot;">​</a></h4><p><img src="'+g+'" alt=""></p><p><strong>点乘的属性</strong></p><p>符合交换律,分配律和结合律</p><p><img src="'+m+'" alt=""></p><p><strong>笛卡尔坐标系中的点乘计算</strong></p><p><img src="'+j+'" alt=""></p><p>图形学中对于点乘的用途</p><ol><li>计算两个向量之间的夹角</li><li>计算一个向量在另一个向量上的投影</li></ol><h4 id="cross-product-叉乘" tabindex="-1">Cross product 叉乘 <a class="header-anchor" href="#cross-product-叉乘" aria-label="Permalink to &quot;Cross product 叉乘&quot;">​</a></h4><p>两个向量的叉乘结果为一个新的向量,并且新的向量与原有两个向量垂直,新的向量确定方向符合右手螺旋定则(四指指向a旋转到b的方向,大拇指为叉乘结构的方向)</p><p><img src="'+f+'" alt=""></p><p><strong>叉乘的属性</strong></p><p><img src="'+h+'" alt=""></p><p><strong>笛卡尔坐标系中的计算</strong></p><p><img src="'+B+'" alt=""></p><p>图形学中对于叉乘的用途</p><ol><li>判断一个向量所处另一个向量的左或者右</li><li>基于上可计算一个点是否在一个封闭区域内</li></ol><h3 id="正交坐标系" tabindex="-1">正交坐标系 <a class="header-anchor" href="#正交坐标系" aria-label="Permalink to &quot;正交坐标系&quot;">​</a></h3><h4 id="三维正交坐标系的初始化-确定三个轴" tabindex="-1">三维正交坐标系的初始化(确定三个轴) <a class="header-anchor" href="#三维正交坐标系的初始化-确定三个轴" aria-label="Permalink to &quot;三维正交坐标系的初始化(确定三个轴)&quot;">​</a></h4><p><img src="'+F+'" alt=""></p><h2 id="matrices-矩阵" tabindex="-1">Matrices 矩阵 <a class="header-anchor" href="#matrices-矩阵" aria-label="Permalink to &quot;Matrices 矩阵&quot;">​</a></h2><p><strong>矩阵在图形学中常用作表示图形变换</strong></p><p><code>Translation,Rotation,Shear,Scale</code></p><h3 id="matrix-矩阵介绍" tabindex="-1">Matrix 矩阵介绍 <a class="header-anchor" href="#matrix-矩阵介绍" aria-label="Permalink to &quot;Matrix 矩阵介绍&quot;">​</a></h3><p><code>m x n matrix = m rows, n columns</code></p><p><strong>矩阵乘法</strong></p><p>条件:前项的列等于后项的行方可进行相乘,结果为一新的矩阵 (m x n)(n x p)=(m x p)</p><p><strong>矩阵属性</strong></p><p>不符合交换律 AB!=BA</p><p>符合分配律和结合律</p><p><img src="'+x+'" alt=""></p><h2 id="transformation-变换" tabindex="-1">Transformation 变换 <a class="header-anchor" href="#transformation-变换" aria-label="Permalink to &quot;Transformation 变换&quot;">​</a></h2><h3 id="scale-matrix-缩放矩阵" tabindex="-1">Scale Matrix 缩放矩阵 <a class="header-anchor" href="#scale-matrix-缩放矩阵" aria-label="Permalink to &quot;Scale Matrix 缩放矩阵&quot;">​</a></h3><p><img src="'+K+'" alt=""></p><h3 id="shear-matrix-剪切矩阵" tabindex="-1">Shear Matrix 剪切矩阵 <a class="header-anchor" href="#shear-matrix-剪切矩阵" aria-label="Permalink to &quot;Shear Matrix 剪切矩阵&quot;">​</a></h3><p><img src="'+D+'" alt=""></p><h3 id="rotation-matrix-旋转矩阵" tabindex="-1">Rotation Matrix 旋转矩阵 <a class="header-anchor" href="#rotation-matrix-旋转矩阵" aria-label="Permalink to &quot;Rotation Matrix 旋转矩阵&quot;">​</a></h3><p><strong>不具体说明时,默认旋转原点为坐标系中心点</strong></p><p><img src="'+R+'" alt=""></p><h3 id="linear-transforms-线性变换" tabindex="-1">Linear Transforms 线性变换 <a class="header-anchor" href="#linear-transforms-线性变换" aria-label="Permalink to &quot;Linear Transforms 线性变换&quot;">​</a></h3><p>以上几种变换矩阵规格相同,可以使用如下矩阵表示</p><p><img src="'+P+'" alt=""></p><h3 id="homogeneous-coordinates-齐次坐标系" tabindex="-1">Homogeneous Coordinates 齐次坐标系 <a class="header-anchor" href="#homogeneous-coordinates-齐次坐标系" aria-label="Permalink to &quot;Homogeneous Coordinates 齐次坐标系&quot;">​</a></h3><p>坐标平移无法只使用上述线性变换矩阵进行表示</p><p><img src="'+d+'" alt=""></p><p><strong>对于点或矢量都添加一项,用于参与矩阵运算,实现支持坐标平移运算</strong></p><p><img src="'+U+'" alt=""></p><p>思考:矢量平移之后得到的新矢量与原矢量保持一致不会发生变化</p><p><img src="'+Q+'" alt=""></p><p>齐次坐标下w分量为1或0</p><p>同样满足向量与点之间的加减运算</p><p>思考:当两个点相加时,可以看作新生成了一个x1=x/w y1=y/w的点,w!=0</p><p><strong>使用齐次坐标进行仿射变换</strong></p><p><img src="'+E+'" alt=""></p><p><strong>2D变换公式</strong></p><p><img src="'+w+'" alt=""></p><h3 id="composing-transforms-复合变换" tabindex="-1">Composing Transforms 复合变换 <a class="header-anchor" href="#composing-transforms-复合变换" aria-label="Permalink to &quot;Composing Transforms 复合变换&quot;">​</a></h3><p><img src="'+H+'" alt=""></p><p><strong>任意点旋转复杂变换矩阵</strong></p><p><img src="'+v+'" alt=""></p><p><strong>3D在齐次坐标下的表示</strong></p><p><img src="'+M+'" alt=""></p><p><img src="'+u+'" alt=""></p><p>思考:默认情况仿射变换中先执行线性变换再执行平移变换,但不是绝对</p>',93),C=[q];function b(k,L,y,N,J,V){return t(),A("div",null,C)}const W=a(I,[["render",b]]);export{X as __pageData,W as default};
